"""Microphone capture pipeline that fans raw PCM blocks out to downstream queues."""

import queue
import time
from dataclasses import dataclass

import sounddevice as sd

DEFAULT_SAMPLE_RATE = 16_000
DEFAULT_BLOCK_SIZE = 1600
DEFAULT_DTYPE = "float32"
DEFAULT_CHANNELS = 1


@dataclass
class AudioPipelineConfig:
    """Capture settings shared by all audio pipelines."""

    sample_rate = DEFAULT_SAMPLE_RATE
    channels = DEFAULT_CHANNELS
    dtype = DEFAULT_DTYPE
    blocksize = DEFAULT_BLOCK_SIZE


class AudioPipeline:
    """Produces a audio input stream (microphone) for downstream consumption."""

    def __init__(self, config: AudioPipelineConfig, audio_queues: list[queue.Queue]):
        self.config = config
        self.audio_queues = audio_queues

    def run_loop(self):
        """Stream microphone audio into the registered queues until interrupted."""
        try:
            with sd.InputStream(
                samplerate=self.config.sample_rate,
                channels=self.config.channels,
                dtype=self.config.dtype,
                callback=self.audio_callback,
                blocksize=self.config.blocksize,
            ):
                print("Recording. Press Ctrl+C to stop.")
                while True:
                    time.sleep(1)
        except KeyboardInterrupt:
            print("Stopping recording.")

    def audio_callback(self, indata, frames, time_info, status):
        """Capture mono PCM from the microphone."""

        for q in self.audio_queues:
            q.put(indata[:, 0].copy())

    @classmethod
    def start_audio_pipeline(
        cls, audio_queues: list[queue.Queue], audio_pipeline_config: AudioPipelineConfig
    ):
        """Starts base audio pipeline to capture microphone audio."""
        AudioPipeline(
            config=audio_pipeline_config, audio_queues=audio_queues
        ).run_loop()

"""Joins ASR segments with diarization segments into speaker-attributed events."""

import queue

from lib.segments import (
    AggregatedSegmentEvent,
    ASRSegmentEvent,
    EventType,
    SpeakerSegmentEvent,
    SpeakerSegmentState,
)


class EventAggregationPipeline:
    """Attributes each transcribed segment to the speaker it overlaps most with."""

    def __init__(
        self, input_event_queue: queue.Queue, aggregated_event_queue: queue.Queue
    ):
        self.input_event_queue: queue.Queue = input_event_queue
        self.aggregated_event_queue: queue.Queue = aggregated_event_queue
        self.queue_timeout = 0.1
        self.min_timestamp_watermark: float = 0
        self.max_timestamp_watermark: float = 0
        self.active_asr_segments: list[ASRSegmentEvent] = []
        self.active_diarization_segments: list[SpeakerSegmentEvent] = []
        self.aggregated_events: list[AggregatedSegmentEvent] = []

    def run_loop(self):
        """Continuously read, aggregate, and publish events."""
        while True:
            # Always
            self.read_events_from_queue()

            # If we have active segments of both types, try to aggregate them
            if (
                len(self.active_asr_segments) >= 1
                and len(self.active_diarization_segments) >= 1
            ):
                self.aggregate_events()

            # If we aggregated events, publish them
            if len(self.aggregated_events) >= 1:
                self.publish_aggregated_events()

                # For now clear in a Naive away
                # Assumes ASR segments always arrive later than diarization segments
                # If events come out of order, a better solution such as watermarking
                # may be required to clear events correctly
                self.clear_aggregation_state()

    def read_events_from_queue(self):
        """Reads all available events.

        Uses the queue timeout parameter as a way to create a window of
        variable size.

        While events keep arriving close together in time (e.g., < 0.1s apart),
        keep waiting/pulling events from queue.

        This adds some latency but ensures events within this boundary are processed
        together.
        """
        try:
            while event := self.input_event_queue.get(timeout=self.queue_timeout):
                if event["type_"] == EventType.asr_segment:
                    self.active_asr_segments.append(ASRSegmentEvent.from_dict(event))
                elif event["type_"] == EventType.diarization_segment:
                    self.active_diarization_segments.append(
                        SpeakerSegmentEvent.from_dict(event)
                    )
                print("Got event: ", event)
        except queue.Empty:
            pass

    def publish_aggregated_events(self):
        """Publishes aggregated events into next event bus."""
        for aggregated_event in self.aggregated_events:
            print("Publishing aggregated event: ", aggregated_event)
            self.aggregated_event_queue.put(aggregated_event.as_dict())

    def clear_aggregation_state(self):
        """Clears all current state, naively.

        Assumes ASR segments always arrive later than diarization segments.

        If events come out of order, a better solution such as watermarking
        may be required to clear events correctly.
        """
        self.active_asr_segments = []
        self.active_diarization_segments = []
        self.aggregated_events = []

    def aggregate_events(self):
        """Aggregates ASR Segments and Diarization Segments."""
        for asr_segment in self.active_asr_segments:
            max_overlap = -1
            max_overlap_segment = None

            for diarization_segment in self.active_diarization_segments:
                # for now, simply ignore segments that are not in closed state
                if diarization_segment.state != SpeakerSegmentState.closed:
                    continue

                overlap_area = asr_segment.overlaps(diarization_segment)
                if overlap_area > max_overlap:
                    max_overlap_segment = diarization_segment
                    max_overlap = overlap_area

            if max_overlap_segment:
                self.aggregated_events.append(
                    AggregatedSegmentEvent.from_events(
                        asr_segment,
                        diarization_segment,
                    )
                )

    @classmethod
    def start_event_aggregation(
        cls, input_event_queue: queue.Queue, output_event_queue: queue.Queue
    ):
        """Entrypoint for running the pipeline in a dedicated process."""
        EventAggregationPipeline(input_event_queue, output_event_queue).run_loop()

"""Event types exchanged between the audio, ASR, diarization, and aggregation stages.

All events serialize to plain dicts so they can cross multiprocessing queues.
Timestamps are in seconds relative to the start of the audio stream.
"""

from dataclasses import dataclass
from enum import StrEnum


class SpeakerSegmentState(StrEnum):
    """Lifecycle state of a diarization segment."""

    closed = "closed"
    open = "open"
    unknown = "unknown"


class EventType(StrEnum):
    """Discriminator carried in each serialized event dict."""

    abstract = "abstract"
    asr_segment = "asr_segment"
    diarization_segment = "diarization_segment"
    aggregated_segment = "aggregated_segment"


@dataclass
class SpeakerSegmentEvent:
    """A span of speech attributed to one speaker by the diarizer."""

    state: SpeakerSegmentState
    speaker: str
    start: float
    end: float | None = None
    type_ = EventType.diarization_segment  # Internal, don't override

    def as_dict(self) -> dict:
        """Serialize the event for transport across process queues."""
        return {
            "state": self.state,
            "speaker": self.speaker,
            "start": self.start,
            "end": self.end,
            "type_": self.type_,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "SpeakerSegmentEvent":
        """Deserialize an event dict, defaulting a missing state to 'unknown'."""
        if "state" not in d:
            d["state"] = "unknown"

        # ignore type_
        if "type_" in d:
            d.pop("type_")

        lower_case = {k.lower(): v for k, v in d.items()}
        return SpeakerSegmentEvent(**lower_case)


@dataclass
class ASRSegmentEvent:
    """A transcribed span of speech, without speaker attribution."""

    start: float
    end: float
    text: str
    type_ = EventType.asr_segment  # Internal, don't override

    def as_dict(self) -> dict:
        """Serialize the event for transport across process queues."""
        return {
            "start": self.start,
            "end": self.end,
            "text": self.text,
            "type_": self.type_,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "ASRSegmentEvent":
        """Deserialize an event dict."""
        lower_case = {k.lower(): v for k, v in d.items()}

        # ignore type_
        if "type_" in lower_case:
            lower_case.pop("type_")

        return ASRSegmentEvent(**lower_case)

    def overlaps(self, segment: SpeakerSegmentEvent) -> float:
        """Seconds of overlap with a closed diarization segment, or -1 if none.

        Only closed segments have a trustworthy end timestamp, so overlap is
        undefined for open/unknown segments and raises ValueError.
        """
        if segment.state != SpeakerSegmentState.closed:
            raise ValueError("Cannot compute overlap on segment that is not closed")

        overlap_area = -1

        # case 1, self is inside segment
        if self.start > segment.start and self.end < segment.end:
            overlap_area = self.end - self.start
            return overlap_area

        # case 2, segment is inside self
        if segment.start > self.start and segment.end < self.end:
            overlap_area = segment.end - segment.start
            return overlap_area

        # case 3, partial overlap, self is on left side
        # e1 > s2 and e2 > s1
        if (
            self.end > segment.start
            and segment.end > self.start
            and self.end < segment.end
        ):
            overlap_area = self.end - segment.start
            return overlap_area

        # case 4, partial overlap, self is on right side
        # e2 > s1 and e1 > s2
        if segment.end > self.start and self.end > segment.start:
            overlap_area = segment.end - self.start
            return overlap_area

        return overlap_area


@dataclass
class AggregatedSegmentEvent:
    """A transcribed span of speech with its attributed speaker.

    Timestamps and text come from the ASR segment; the speaker comes from the
    diarization segment it overlapped most with.
    """

    start: float
    end: float
    text: str
    speaker: str
    type_ = EventType.aggregated_segment  # Internal, don't override

    def as_dict(self) -> dict:
        """Serialize the event for transport across process queues."""
        return {
            "start": self.start,
            "end": self.end,
            "text": self.text,
            "speaker": self.speaker,
            "type_": self.type_,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "AggregatedSegmentEvent":
        """Deserialize an event dict."""
        lower_case = {k.lower(): v for k, v in d.items()}

        # ignore type_
        if "type_" in lower_case:
            lower_case.pop("type_")

        return AggregatedSegmentEvent(**lower_case)

    @classmethod
    def from_events(
        cls,
        asr_segment_event: ASRSegmentEvent,
        speaker_segment_event: SpeakerSegmentEvent,
    ) -> "AggregatedSegmentEvent":
        """Combine an ASR segment with the diarization segment it overlaps most."""
        # Read only speaker from speaker segment, use timestamps from ASR Segmente Event as source of truth
        return AggregatedSegmentEvent(
            start=asr_segment_event.start,
            end=asr_segment_event.end,
            text=asr_segment_event.text,
            speaker=speaker_segment_event.speaker,
        )

"""Forwards aggregated transcription events from a queue to the voice assistant API."""

import queue

from lib.api_sdk import AgentAPI, ApiConfig
from lib.segments import AggregatedSegmentEvent


class ApiPipeline:
    """Consumes aggregated events and POSTs each one to the assistant server."""

    def __init__(self, event_queue: queue.Queue):
        self.event_queue = event_queue
        self.agent_api = AgentAPI(ApiConfig())

    def run_loop(self):
        """Poll the event queue forever, forwarding each event to the API."""
        while True:
            try:
                event = self.event_queue.get(timeout=1)
                self.send_event_to_api(AggregatedSegmentEvent.from_dict(event))
            except queue.Empty:
                pass

    def send_event_to_api(self, event: AggregatedSegmentEvent):
        """Send a single aggregated event's text and speaker to the API."""
        self.agent_api.api_call(text=event.text, speaker=event.speaker)

    @classmethod
    def start_api_sync(cls, event_queue: queue.Queue):
        """Entrypoint for running the pipeline in a dedicated process."""
        ApiPipeline(event_queue).run_loop()

"""HTTP client for the voice assistant server in `main.py`."""

from dataclasses import dataclass

import requests


@dataclass
class ApiConfig:
    """Connection settings for the assistant server."""

    hostname: str = "http://127.0.0.1"
    port: int = 8000

    @property
    def as_url(self) -> str:
        """Base URL of the server."""
        return f"{self.hostname}:{self.port}"


class AgentAPI:
    """Thin wrapper that POSTs transcription events to the server."""

    def __init__(self, config: ApiConfig):
        self.config = config

    def api_call(self, text, speaker):
        """Send one transcription event (text + speaker id) to the server."""
        print(f"Sending [speaker {speaker}]: {text}")
        response = requests.post(
            self.config.as_url,
            json={
                "data": {
                    "transcription": text,
                    "speaker": speaker,
                }
            },
        )
        print(f"Response Status Code: {response.status_code}")
        print(f"Response Text: {response.text}")

"""Minimal chat-history model that serializes to the OpenAI messages format."""

from dataclasses import dataclass, field
from enum import StrEnum


class OpenAIRole(StrEnum):
    """Roles accepted by the OpenAI chat-completions schema."""

    user = "user"
    assistant = "assistant"
    system = "system"


@dataclass
class OpenAIMessage:
    """A single chat message with an OpenAI role and text content."""

    role: OpenAIRole
    content: str

    def as_dict(self):
        """Serialize to the `{"role": ..., "content": ...}` wire format."""
        return {"role": self.role.value, "content": self.content}


@dataclass
class Chat:
    """Ordered chat history for the session."""

    messages: list[OpenAIMessage] = field(default_factory=list)

    def add_system_instruction(self, text: str):
        """Append a system-prompt message."""
        print(f"Adding system instruction: {text}")
        self.messages.append(OpenAIMessage(role=OpenAIRole.system, content=text))

    def add_user_message(self, text: str):
        """Append a user message."""
        print(f"Adding user message: {text}")
        self.messages.append(OpenAIMessage(role=OpenAIRole.user, content=text))

    def add_model_response(self, text: str):
        """Append an assistant message."""
        print(f"Adding model response model: {text}")
        self.messages.append(OpenAIMessage(role=OpenAIRole.assistant, content=text))

    def to_openai_prompt(self) -> list:
        """Serialize the full history as an OpenAI-style messages list."""
        chat_text = []
        for message in self.messages:
            chat_text.append(message.as_dict())
        return chat_text

